    cylinder("Control knob", (0.095, 0.026, 0.16), 0.022, 0.016, dark, 0.002, (0, math.pi / 2, 0))
    cylinder("Control knob cap", (0.105, 0.026, 0.16), 0.014, 0.002, brass, 0.001, (0, math.pi / 2, 0))
