        self.mouths = {}
        self.mouths["X"] = ArcBetweenPoints(p(-0.20, 1.03), p(0.20, 1.03), angle=0.45, color=PALETTE["mint"], stroke_width=3)
        self.mouths["A"] = Line(p(-0.20, 1.02), p(0.20, 1.02), color=PALETTE["ink"], stroke_width=3)
