function argument(name) {
  const index = process.argv.indexOf(name);
  const value = index === -1 ? undefined : process.argv[index + 1];
  if (value === undefined || value === "") {
    throw new Error("Missing workflow-bundler guardian argument: " + name);
  }
  return value;
}

